140		decoder := json.NewDecoder(body)
141		if err := decoder.Decode(&raw); err != nil {
142			return store.Record{}, false
143		}
144		var trailing any
145		if err := decoder.Decode(&trailing); err != io.EOF {
146			return store.Record{}, false
147		}
148	
149		var rec store.Record
150		var ok bool
151		if rec.Namespace, ok = requiredString(raw, "namespace"); !ok {
152			return store.Record{}, false
153		}
154		if rec.Name, ok = requiredString(raw, "name"); !ok {
155			return store.Record{}, false
156		}
157		if rec.Label, ok = requiredString(raw, "label"); !ok {
158			return store.Record{}, false
159		}
160		if rec.Rules, ok = decodeRules(raw); !ok {
161			return store.Record{}, false
162		}
