185	func decodeRules(raw map[string]json.RawMessage) ([]store.Rule, bool) {
186		blob, present := raw["rules"]
187		if !present {
188			return nil, false
189		}
190		var items []json.RawMessage
191		if err := json.Unmarshal(blob, &items); err != nil || len(items) == 0 {
192			return nil, false
193		}
194		rules := make([]store.Rule, 0, len(items))
195		for _, item := range items {
196			var fields map[string]json.RawMessage
197			if err := json.Unmarshal(item, &fields); err != nil {
198				return nil, false
199			}
200			direction, ok := requiredEnum(fields, "direction", "ingress", "egress")
201			if !ok {
