213			if err := json.Unmarshal(portsBlob, &ports); err != nil || len(ports) != 2 {
214				return nil, false
215			}
216			if ports[0] < 1 || ports[0] > 65535 || ports[1] < 1 || ports[1] > 65535 || ports[0] > ports[1] {
217				return nil, false
218			}
219			rules = append(rules, store.Rule{Direction: direction, Action: action, Ports: [2]int{ports[0], ports[1]}})
220		}
221		return rules, true
