602			"object hidden by later string":            `{"mode": {"x": 1}, "mode": "enforce"}`,
603			"legal string hidden by later null":        `{"mode": "enforce", "mode": null}`,
604			"escaped name null first, literal legal":   `{"\u006dode": null, "mode": "enforce"}`,
605			"literal legal first, escaped name null":   `{"mode": "enforce", "\u006dode": null}`,
606			"escaped name number, literal legal after": `{"\u006dode": 7, "mode": "enforce"}`,
607			"two illegal occurrences around a legal":   `{"mode": false, "retries": "3", "mode": null}`,
608		}
609		for name, params := range cases {
610			t.Run(name, func(t *testing.T) {
611				router, _ := newTestRouter(t)
612				bad := policyBody("payments", "default-deny", "tier=backend", params)
613	
614				recorder := doRequest(router, http.MethodPost, "/v1/net-policies", bad)
615				if recorder.Code != http.StatusBadRequest {
616					t.Fatalf("status = %d, want %d: %s", recorder.Code, http.StatusBadRequest, recorder.Body.String())
617				}
618				assertErrorCode(t, recorder, "InvalidNetPolicyInputError")
619				assertSafeErrorMessage(t, recorder)
620	
621				// A rejected new identity leaves no record behind.
622				for _, target := range []string{
623					"/v1/net-policies?namespace=payments",
624					"/v1/net-policies?label=tier%3Dbackend",
625				} {
626					miss := doRequest(router, http.MethodGet, target, "")
627					if miss.Code != http.StatusNotFound {
628						t.Fatalf("GET %s status = %d, want %d", target, miss.Code, http.StatusNotFound)
629					}
630					assertErrorCode(t, miss, "NetPolicyNotFoundError")
631				}
632	
633				// The rejected registration must not consume an order value.
634				good := policyBody("payments", "default-deny", "tier=backend", `{"mode": "enforce"}`)
635				created := doRequest(router, http.MethodPost, "/v1/net-policies", good)
636				if created.Code != http.StatusCreated {
637					t.Fatalf("valid status = %d, want %d: %s", created.Code, http.StatusCreated, created.Body.String())
638				}
639				var stored map[string]any
640				if err := json.Unmarshal(created.Body.Bytes(), &stored); err != nil {
641					t.Fatalf("decode: %v", err)
642				}
643				if stored["order"] != float64(1) {
644					t.Fatalf("order = %v, want 1 (rejected request must not consume an order)", stored["order"])
645				}
646			})
647		}
648	}
649	
650	// Posting a duplicate-name pluginParams against an existing identity is invalid
651	// input whenever any occurrence is non-string, even if the final value equals
652	// the stored one (never 200) or differs (never 409). The committed record, its
653	// order and its conflict flag stay untouched.
654	func TestPostNetPolicyDuplicateMemberIllegalOnExistingIdentity(t *testing.T) {
655		cases := []struct {
656			name        string
657			retryParams string
658		}{
659			{"illegal hidden by value equal to stored", `{"mode": null, "mode": "enforce"}`},
660			{"illegal hidden by value differing stored", `{"mode": null, "mode": "audit"}`},
661			{"legal then illegal, final differs", `{"mode": "enforce", "retries": "3", "mode": null}`},
662			{"escaped illegal occurrence", `{"mode": "enforce", "\u006dode": null}`},
663		}
664		for _, tc := range cases {
665			t.Run(tc.name, func(t *testing.T) {
666				router, _ := newTestRouter(t)
667				// A clashing rule first so the seed record carries conflict=true,
668				// which the rejected retry must leave intact.
669				clash := policyWithRules("payments", "clash", "tier=backend",
670					`[{"direction":"ingress","action":"deny","ports":[80,80]}]`, `{}`)
671				if rec := doRequest(router, http.MethodPost, "/v1/net-policies", clash); rec.Code != http.StatusCreated {
672					t.Fatalf("clash seed status = %d: %s", rec.Code, rec.Body.String())
673				}
674				seed := doRequest(router, http.MethodPost, "/v1/net-policies",
675					policyBody("payments", "default-deny", "tier=backend", `{"mode": "enforce"}`))
676				if seed.Code != http.StatusCreated {
677					t.Fatalf("seed status = %d: %s", seed.Code, seed.Body.String())
678				}
679				var seedRecord map[string]any
680				if err := json.Unmarshal(seed.Body.Bytes(), &seedRecord); err != nil {
681					t.Fatalf("decode seed: %v", err)
682				}
683				if seedRecord["conflict"] != true {
684					t.Fatalf("seed conflict = %v, want true", seedRecord["conflict"])
685				}
686	
687				retry := doRequest(router, http.MethodPost, "/v1/net-policies",
688					policyBody("payments", "default-deny", "tier=backend", tc.retryParams))
689				if retry.Code != http.StatusBadRequest {
690					t.Fatalf("retry status = %d, want %d (never 200 or 409): %s",
691						retry.Code, http.StatusBadRequest, retry.Body.String())
692				}
693				assertErrorCode(t, retry, "InvalidNetPolicyInputError")
694				assertSafeErrorMessage(t, retry)
695	
696				items := listItems(t, router, "/v1/net-policies?namespace=payments")
697				if len(items) != 2 {
698					t.Fatalf("items = %v, want the two original records only", items)
699				}
700				var original map[string]any
701				for _, item := range items {
702					if item["name"] == "default-deny" {
703						original = item
704					}
705				}
706				if original == nil {
707					t.Fatalf("seed record missing after rejected retry: %v", items)
708				}
709				if !reflect.DeepEqual(original, seedRecord) {
710					t.Fatalf("record changed after rejected retry:\n got %v\nwant %v", original, seedRecord)
711				}
712			})
713		}
714	}
715	
716	// When every occurrence of a repeated member name is a string the request stays
717	// valid: the last occurrence after JSON key unescaping wins, and only the final
718	// key/value object is presented in the response and in queries. Special legal
719	// strings (empty, whitespace, Chinese, the literal "null") keep working when
720	// repeated.
721	func TestPostNetPolicyDuplicateMembersAllStringsLastWins(t *testing.T) {
722		cases := []struct {
723			name       string
724			identity   string
725			paramsJSON string
726			want       map[string]any
727		}{
728			{"literal duplicate last wins", "dup-literal",
729				`{"mode": "audit", "mode": "enforce"}`, map[string]any{"mode": "enforce"}},
730			{"escaped duplicate last wins", "dup-escaped",
731				`{"\u006dode": "audit", "mode": "enforce"}`, map[string]any{"mode": "enforce"}},
732			{"escaped first then literal", "dup-escaped-first",
733				`{"\u006dode": "enforce", "mode": "audit"}`, map[string]any{"mode": "audit"}},
734			{"duplicates separated by other members", "dup-separated",
735				`{"a": "1", "mode": "audit", "b": "2", "mode": "enforce"}`,
736				map[string]any{"a": "1", "b": "2", "mode": "enforce"}},
737			{"empty string then non-empty", "dup-empty-first",
738				`{"mode": "", "mode": "enforce"}`, map[string]any{"mode": "enforce"}},
739			{"non-empty then empty string", "dup-empty-last",
740				`{"mode": "enforce", "mode": ""}`, map[string]any{"mode": ""}},
741			{"whitespace, chinese and literal null repeated", "dup-special",
742				`{"mode": "null", "\u006dode": " 拦截 "}`, map[string]any{"mode": " 拦截 "}},
743		}
744		for _, tc := range cases {
745			t.Run(tc.name, func(t *testing.T) {
746				router, _ := newTestRouter(t)
747				body := policyBody("payments", tc.identity, "tier=backend", tc.paramsJSON)
748				created := doRequest(router, http.MethodPost, "/v1/net-policies", body)
749				if created.Code != http.StatusCreated {
750					t.Fatalf("status = %d, want %d: %s", created.Code, http.StatusCreated, created.Body.String())
751				}
752				var resp map[string]any
753				if err := json.Unmarshal(created.Body.Bytes(), &resp); err != nil {
754					t.Fatalf("decode: %v", err)
755				}
756				if !reflect.DeepEqual(resp["pluginParams"], tc.want) {
757					t.Fatalf("response pluginParams = %v, want %v", resp["pluginParams"], tc.want)
758				}
759	
760				items := listItems(t, router, "/v1/net-policies?namespace=payments")
761				if len(items) != 1 || !reflect.DeepEqual(items[0]["pluginParams"], tc.want) {
762					t.Fatalf("stored pluginParams = %v, want %v", items, tc.want)
763				}
764			})
765		}
766	}
767	
768	// A retry of an identity created from duplicate member names returns 200 with
769	// the original record when the final content matches, regardless of how the
770	// members are spelled, consumes no order, and the following fresh identity
771	// takes the next sequence value.
772	func TestPostNetPolicyDuplicateMembersIdempotentRetryAndOrder(t *testing.T) {
773		router, _ := newTestRouter(t)
774		seed := policyBody("payments", "default-deny", "tier=backend",
775			`{"a": "1", "mode": "audit", "mode": "enforce"}`)
776		if rec := doRequest(router, http.MethodPost, "/v1/net-policies", seed); rec.Code != http.StatusCreated {
777			t.Fatalf("seed status = %d: %s", rec.Code, rec.Body.String())
778		}
779	
780		// Same final content, single occurrence this time.
781		retry := doRequest(router, http.MethodPost, "/v1/net-policies",
782			policyBody("payments", "default-deny", "tier=backend", `{"mode": "enforce", "a": "1"}`))
783		if retry.Code != http.StatusOK {
784			t.Fatalf("retry status = %d, want %d: %s", retry.Code, http.StatusOK, retry.Body.String())
785		}
786		var body map[string]any
787		if err := json.Unmarshal(retry.Body.Bytes(), &body); err != nil {
788			t.Fatalf("decode retry: %v", err)
789		}
790		if body["order"] != float64(1) {
791			t.Fatalf("retry order = %v, want original 1", body["order"])
792		}
793		wantParams := map[string]any{"a": "1", "mode": "enforce"}
794		if !reflect.DeepEqual(body["pluginParams"], wantParams) {
795			t.Fatalf("retry pluginParams = %v, want %v", body["pluginParams"], wantParams)
796		}
797	
798		// Different final content is still a conflict rather than an overwrite.
799		conflict := doRequest(router, http.MethodPost, "/v1/net-policies",
800			policyBody("payments", "default-deny", "tier=backend",
801				`{"mode": "audit", "mode": "audit"}`))
802		if conflict.Code != http.StatusConflict {
803			t.Fatalf("changed retry status = %d, want %d: %s", conflict.Code, http.StatusConflict, conflict.Body.String())
804		}
805		assertErrorCode(t, conflict, "NetPolicyConflictError")
806	
807		next := doRequest(router, http.MethodPost, "/v1/net-policies",
808			policyBody("payments", "after", "tier=backend",
809				`{"mode": "x", "mode": "x"}`))
810		if next.Code != http.StatusCreated {
811			t.Fatalf("next status = %d, want %d: %s", next.Code, http.StatusCreated, next.Body.String())
812		}
813		json.Unmarshal(next.Body.Bytes(), &body)
814		if body["order"] != float64(2) {
815			t.Fatalf("next order = %v, want 2", body["order"])
816		}
817		if !reflect.DeepEqual(body["pluginParams"], map[string]any{"mode": "x"}) {
818			t.Fatalf("next pluginParams = %v, want single final key", body["pluginParams"])
819		}
820	
821		items := listItems(t, router, "/v1/net-policies?namespace=payments")
822		if len(items) != 2 {
823			t.Fatalf("items = %v, want 2 records", items)
824		}
825	}
826	
827	func assertErrorCode(t *testing.T, recorder *httptest.ResponseRecorder, want string) {
828		t.Helper()
829		var body map[string]map[string]string
830		if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
831			t.Fatalf("decode error body: %v", err)
832		}
833		if body["error"]["code"] != want {
834			t.Fatalf("error.code = %q, want %q (body %s)", body["error"]["code"], want, recorder.Body.String())
835		}
836		if body["error"]["message"] == "" {
837			t.Fatalf("error.message is empty (body %s)", recorder.Body.String())
838		}
839	}
