267	// Rejected requests (409 content conflict, 400 invalid input) and same-content
268	// retries neither add records nor change any committed field — including the
269	// conflict flags — and the next legal policy continues at max order + 1.
270	func TestRejectedAndRetriedRequestsLeaveRegistryUntouched(t *testing.T) {
271		router, _ := newTestRouter(t)
272	
273		seedBody := singleRuleBody("payments", "deny-web", "tier=backend", "ingress", "deny", 80, 100, `{"mode": "enforce"}`)
274		seed := registerCreated(t, router, seedBody, 1, false)
275		clashBody := singleRuleBody("payments", "allow-web", "tier=backend", "ingress", "allow", 100, 200,
276			`{"mode": "enforce", "zone": "east"}`)
277		clash := registerCreated(t, router, clashBody, 2, true)
278	
279		// Legal change of a plugin string value on an existing identity: 409.
280		changed := singleRuleBody("payments", "deny-web", "tier=backend", "ingress", "deny", 80, 100, `{"mode": "audit"}`)
281		recorder := doRequest(router, http.MethodPost, "/v1/net-policies", changed)
282		if recorder.Code != http.StatusConflict {
283			t.Fatalf("changed status = %d, want %d: %s", recorder.Code, http.StatusConflict, recorder.Body.String())
284		}
285		assertExactErrorShape(t, recorder, "NetPolicyConflictError")
286		assertSafeErrorMessage(t, recorder)
287	
288		// Invalid direction and out-of-range port on fresh identities: 400.
289		for name, body := range map[string]string{
290			"bad direction":    singleRuleBody("payments", "bad-dir", "tier=backend", "sideways", "allow", 80, 80, `{}`),
291			"port below range": singleRuleBody("payments", "bad-port", "tier=backend", "ingress", "allow", 0, 80, `{}`),
292			"port above range": singleRuleBody("payments", "bad-port2", "tier=backend", "ingress", "allow", 1, 65536, `{}`),
293		} {
294			recorder := doRequest(router, http.MethodPost, "/v1/net-policies", body)
295			if recorder.Code != http.StatusBadRequest {
296				t.Fatalf("%s status = %d, want %d: %s", name, recorder.Code, http.StatusBadRequest, recorder.Body.String())
297			}
298			assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
299			assertSafeErrorMessage(t, recorder)
300		}
301	
302		// Same-content retry with reordered pluginParams members: 200, original record.
303		retryBody := singleRuleBody("payments", "allow-web", "tier=backend", "ingress", "allow", 100, 200,
304			`{"zone": "east", "mode": "enforce"}`)
305		recorder = doRequest(router, http.MethodPost, "/v1/net-policies", retryBody)
306		if recorder.Code != http.StatusOK {
307			t.Fatalf("retry status = %d, want %d: %s", recorder.Code, http.StatusOK, recorder.Body.String())
308		}
309		var resp map[string]any
310		if err := json.Unmarshal(recorder.Body.Bytes(), &resp); err != nil {
311			t.Fatalf("decode retry: %v", err)
312		}
313		if !reflect.DeepEqual(resp, clash) {
314			t.Fatalf("retry record = %v, want the original %v", resp, clash)
315		}
316	
317		// A filter matching nothing still reports 404 with the published shape.
318		miss := doRequest(router, http.MethodGet, "/v1/net-policies?label=tier%3Dmissing", "")
319		if miss.Code != http.StatusNotFound {
320			t.Fatalf("miss status = %d, want %d", miss.Code, http.StatusNotFound)
321		}
322		assertExactErrorShape(t, miss, "NetPolicyNotFoundError")
323		assertSafeErrorMessage(t, miss)
324	
325		// Nothing was added and nothing committed changed.
326		items := listItems(t, router, "/v1/net-policies?namespace=payments")
327		if want := []map[string]any{seed, clash}; !reflect.DeepEqual(items, want) {
328			t.Fatalf("items after rejections/retries = %v, want unchanged %v", items, want)
329		}
330	
331		// The next legal new policy takes the current maximum order plus one.
332		nextBody := singleRuleBody("payments", "next", "tier=backend", "egress", "allow", 53, 53, `{}`)
333		registerCreated(t, router, nextBody, 3, false)
334	}
