138	// assertExactErrorBytes is the []byte counterpart of assertExactErrorShape:
139	// exactly one top-level "error" object holding string code and non-empty
140	// message, with no other members.
141	func assertExactErrorBytes(t *testing.T, status int, raw []byte, wantStatus int, wantCode string) {
142		t.Helper()
143		if status != wantStatus {
144			t.Fatalf("status = %d, want %d: %s", status, wantStatus, string(raw))
145		}
146		var top map[string]json.RawMessage
147		if err := json.Unmarshal(raw, &top); err != nil {
148			t.Fatalf("decode error body: %v", err)
149		}
150		if len(top) != 1 {
151			t.Fatalf("error body has %d top-level keys, want exactly one (error): %s", len(top), string(raw))
152		}
153		errRaw, ok := top["error"]
154		if !ok {
155			t.Fatalf("error body missing top-level error object: %s", string(raw))
156		}
157		var errObj map[string]json.RawMessage
158		if err := json.Unmarshal(errRaw, &errObj); err != nil {
159			t.Fatalf("error member is not an object: %v", err)
160		}
161		if len(errObj) != 2 {
162			t.Fatalf("error object has %d members, want exactly code and message: %s", len(errObj), string(raw))
163		}
164		var code, message string
165		if err := json.Unmarshal(errObj["code"], &code); err != nil {
166			t.Fatalf("error.code is not a string: %s", string(raw))
167		}
168		if err := json.Unmarshal(errObj["message"], &message); err != nil {
169			t.Fatalf("error.message is not a string: %s", string(raw))
170		}
171		if code != wantCode {
172			t.Fatalf("error.code = %q, want %q (body %s)", code, wantCode, string(raw))
173		}
174		if message == "" {
175			t.Fatalf("error.message is empty: %s", string(raw))
176		}
177		for _, leak := range []string{"sql", "sqlite", "goroutine", ".go:", "panic", "/", "\\"} {
178			if strings.Contains(strings.ToLower(message), leak) {
179				t.Fatalf("error.message leaks %q: %s", leak, message)
180			}
181		}
182	}
