	db, err := sql.Open("sqlite", s.path)
	if err != nil {
		t.Fatalf("reopen sqlite: %v", err)
	}
	db.SetMaxOpenConns(1)
	if err := db.Ping(); err != nil {
		db.Close()
		t.Fatalf("reopened database is not usable: %v", err)
	}
	s.db = db
	s.down = false
}

